/* ===== BLUEGPT RETRO-RELAXING THEME FOR CHROME ===== */

/* ===== BACKGROUND WALLPAPER ===== */
body::before {
    content: "";
    position: fixed;
    top: 0; left: 0;
    width: 100%; height: 100%;
    background: url("https://getwallpapers.com/wallpaper/full/d/2/7/1498104-cool-mind-relaxing-wallpapers-1920x1240-high-resolution.jpg") no-repeat center center fixed;
    background-size: cover;
    z-index: -9999;
    pointer-events: none;
}

/* ===== GENERAL FONT AND COLORS ===== */
body, input, textarea, select, button {
    font-family: 'Segoe UI', 'Courier New', monospace !important;
    color: #e0e7ff !important;
    background: transparent !important;
}

/* ===== LINKS ===== */
a {
    color: #99cfff !important;
    text-decoration: none !important;
    transition: color 0.2s, text-shadow 0.2s;
}
a:hover {
    color: #ffffff !important;
    text-shadow: 0 0 4px #99cfff !important;
}

/* ===== BUTTONS ===== */
button {
    background: #3a50c4 !important;
    color: #e0e7ff !important;
    border-radius: 6px !important;
    border: none !important;
    cursor: pointer !important;
    transition: all 0.2s !important;
}
button:hover {
    background: #5a6ff0 !important;
    transform: translateY(-2px) !important;
}

/* ===== INPUTS & ADDRESS BARS ===== */
input, textarea {
    background: rgba(255,255,255,0.05) !important;
    border: 1px solid #99cfff !important;
    color: #e0e7ff !important;
    border-radius: 6px !important;
    padding: 4px 8px !important;
    font-family: 'Courier New', monospace !important;
}

/* ===== SLIDERS ===== */
input[type="range"] {
    -webkit-appearance: none !important;
    width: 100% !important;
    height: 6px !important;
    background: #99cfff !important;
    border-radius: 4px !important;
}
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none !important;
    width: 16px !important;
    height: 16px !important;
    background: #3a50c4 !important;
    border-radius: 50% !important;
    cursor: pointer !important;
    transition: background 0.2s, transform 0.2s !important;
}
input[type="range"]::-webkit-slider-thumb:hover {
    background: #5a6ff0 !important;
    transform: scale(1.2) !important;
}

/* ===== SCROLLBAR ===== */
::-webkit-scrollbar { width: 10px; }
::-webkit-scrollbar-track { background: rgba(255,255,255,0.05); border-radius: 6px; }
::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.2); border-radius: 6px; }
::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.4); }

/* ===== OPTIONAL RETRO SHADOWS ===== */
* {
    text-shadow: 0 0 2px rgba(0,0,0,0.3);
    transition: all 0.2s !important;
}
